package ir.hawraa.quran.data.quran

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Wire shape of `assets/quran/pages-v1.json`. Generated by
 * `tools/build-quran-assets.py` — do not hand-edit the asset.
 */
@Serializable
internal data class QuranContentDto(
    val schemaVersion: Int,
    val mushaf: String,
    val basmalaUthmani: String,
    val surahs: List<SurahDto>,
    val pages: List<PageDto>,
)

@Serializable
internal data class SurahDto(
    val number: Int,
    val nameArabic: String,
    val nameFa: String,
    val nameEn: String,
    val ayahCount: Int,
    val revelationPlace: String,
    val bismillahPre: Boolean,
)

@Serializable
internal data class PageDto(
    val page: Int,
    val juz: Int,
    val verses: List<VerseDto>,
)

@Serializable
internal data class VerseDto(
    val key: String,
    val surah: Int,
    val ayah: Int,
    val textUthmani: String,
    /**
     * Single-translation form, which is what `tools/build-quran-assets.py` writes today.
     * [translations] is the forward-compatible form: when a second translation lands, the
     * script emits that array and this field disappears — no reader change either way.
     */
    val translationFa: String = "",
    val translations: List<TranslationDto> = emptyList(),
    val juz: Int,
    val hizb: Int,
    @SerialName("rubElHizb") val rubElHizb: Int,
    val sajdah: Int? = null,
)

@Serializable
internal data class TranslationDto(
    val key: String,
    val text: String,
)
